const items = $input.all();
const results = [];
for (const item of items) {
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    const bin = item.binary[key];
    const ext = (bin.fileName || '').split('.').pop().toLowerCase();
    let sourceFormat = 'unknown';
    if (['pdf'].includes(ext) || bin.mimeType === 'application/pdf') sourceFormat = 'pdf';
    else if (['docx', 'doc'].includes(ext)) sourceFormat = 'docx';
    else if (['html', 'htm'].includes(ext)) sourceFormat = 'html';
    else if (['txt'].includes(ext)) sourceFormat = 'text';
    else if (['xlsx', 'xls'].includes(ext)) sourceFormat = 'excel';
    const targetFormat = item.json.body?.targetFormat || (sourceFormat === 'pdf' ? 'docx' : 'pdf');
    results.push({
      json: {
        fileKey: key,
        fileName: bin.fileName,
        sourceFormat,
        targetFormat,
        mimeType: bin.mimeType
      },
      binary: { [key]: bin }
    });
  }
}
return results;
